/* Portfolio 1 #peek concept: eased position + small velocity-based rotation.
   Only one on-demand animation frame runs; bounds are measured outside the frame loop. */
(()=>{'use strict';const peek=document.querySelector('#peek'),grid=document.querySelector('#grid'),projects=window.PORTFOLIO_PROJECTS,visuals=window.PORTFOLIO_VISUALS,fine=matchMedia('(hover:hover) and (pointer:fine)'),reduce=matchMedia('(prefers-reduced-motion: reduce)');
let active=null,mode='',frame=0,lastTime=0,x=0,y=0,tx=0,ty=0,w=320,h=265,vw=innerWidth,vh=innerHeight;
const isReduced=()=>reduce.matches||document.documentElement.dataset.motion==='off';
const clamp=(v,min,max)=>Math.max(min,Math.min(v,Math.max(min,max)));
function measure(){const r=peek.getBoundingClientRect();w=r.width||320;h=r.height||265;vw=innerWidth;vh=innerHeight}
function bounds(px,py){const margin=24;return{x:clamp(px,margin,vw-w-margin),y:clamp(py,margin,vh-h-margin)}}
function stop(){cancelAnimationFrame(frame);frame=0;lastTime=0}
function hide(){peek.classList.remove('on');active=null;mode='';stop()}
function paint(angle=0){peek.style.transform=`translate3d(${x.toFixed(2)}px,${y.toFixed(2)}px,0) rotate(${angle.toFixed(2)}deg)`}
function tick(time){frame=0;if(!active)return;const dt=lastTime?Math.min(40,time-lastTime):16;lastTime=time;const dx=tx-x,dy=ty-y,k=isReduced()?1:1-Math.exp(-dt*.0094);x+=dx*k;y+=dy*k;paint(isReduced()||mode==='keyboard'?0:clamp(dx*.035,-3,3));if(Math.abs(dx)+Math.abs(dy)>.15)frame=requestAnimationFrame(tick);else{x=tx;y=ty;paint();lastTime=0}}
function animate(){if(!frame)frame=requestAnimationFrame(tick)}
function targetPointer(e){if(!active||mode!=='pointer')return;const left=e.clientX+24+w+24>vw?e.clientX-w-24:e.clientX+24;const p=bounds(left,e.clientY-h*.55);tx=p.x;ty=p.y;animate()}
function show(card,kind,e){if(!fine.matches||document.querySelector('dialog[open]'))return;const p=projects.find(p=>p.id===card.dataset.id);if(!p)return;active=card;mode=kind;const v=peek.querySelector('.peek-visual');v.className='peek-visual '+p.category;v.innerHTML=visuals.visual(p);const caption=peek.querySelector('.peek-caption');caption.replaceChildren(document.createTextNode(p.title));const s=document.createElement('span');s.textContent=p.media.length?'Original project image · open for details':'Visual placeholder · screenshot not available';caption.append(s);measure();if(kind==='keyboard'||isReduced()){mode='keyboard';const r=card.getBoundingClientRect(),pos=bounds(r.right+20+w<vw?r.right+20:r.left-w-20,r.top);tx=x=pos.x;ty=y=pos.y;paint()}else{targetPointer(e);x=tx;y=ty;paint()}peek.classList.add('on')}
// Delegation survives category/search renders. Touch click opens the static drawer instead.
grid.addEventListener('pointerover',e=>{if(e.pointerType==='touch')return;const c=e.target.closest('.card');if(c&&(c!==active||mode!=='pointer'))show(c,'pointer',e)});grid.addEventListener('pointerout',e=>{if(mode==='pointer'&&active&&!active.contains(e.relatedTarget))hide()});grid.addEventListener('focusin',e=>{const c=e.target.closest('.card');if(c&&c.matches(':focus-visible'))show(c,'keyboard')});grid.addEventListener('focusout',e=>{if(mode==='keyboard'&&!active?.contains(e.relatedTarget))hide()});addEventListener('pointermove',e=>{if(!isReduced())targetPointer(e)},{passive:true});addEventListener('scroll',()=>{if(mode==='pointer')hide()},{passive:true});addEventListener('resize',()=>{hide();measure()},{passive:true});addEventListener('blur',hide);document.addEventListener('portfolio:projectchange',hide);document.addEventListener('portfolio:draweropen',hide);document.addEventListener('portfolio:motionchange',hide);fine.addEventListener('change',hide);reduce.addEventListener('change',hide);document.addEventListener('visibilitychange',()=>{if(document.hidden)hide()});measure();
})();
